"""Render the engineering analysis report (Markdown) from the summary dataset."""

from __future__ import annotations

from typing import Any


def _f(v: float | None, d: int = 0) -> str:
    return "n/a" if v is None else f"{v:,.{d}f}"


def render(summary: dict[str, Any]) -> str:
    env = summary["environment"]
    accs = ", ".join(f"{a['backend']}: {a['name']}" for a in env.get("accelerators") or [])
    out = [
        "# Performance analysis (generated)",
        "",
        "> Generated by `gpulab analyze` from the records in `results/`. Every number below is",
        "> labeled by evidence type: **measured** (read from records), **derived** (computed from",
        "> measured values), or **theoretical** (from specifications). Do not edit by hand.",
        "",
        f"- Generated: {summary['generated_utc']}",
        f"- Hardware: {env.get('cpu')}, {env.get('memory_gib')} GiB; accelerators: {accs}",
        f"- Software: {env.get('os')}, Python {env.get('python')}, PyTorch {env.get('torch')}",
        f"- Records from commit: `{(env.get('git_commit') or 'n/a')[:7]}`",
        "",
        "## Unavailable (not measured, not estimated)",
        "",
        *[f"- {u}" for u in summary["unavailable"]],
        "",
        "## Paired comparisons against eager (derived; 95% bootstrap CI over interleaved trials)",
        "",
        "| device | dtype | model | mode | impl | rows | eager p50 µs | impl p50 µs | speedup | verdict |",
        "|---|---|---|---|---|---|---|---|---|---|",
    ]
    for c in summary["comparisons"]:
        out.append(
            f"| {c['device']} | {c['dtype']} | {c['d_model']}×{c['d_hidden']}×{c['depth']} "
            f"| {c['mode']} | {c['candidate']} | {c['rows']} | {_f(c['baseline_p50_us'])} "
            f"| {_f(c['candidate_p50_us'])} | {c['speedup_geomean']:.2f}× "
            f"[{c['ci_low']:.2f}, {c['ci_high']:.2f}] | {c['verdict']} |"
        )
    out += ["", "## Regressions (CI entirely below 1)", ""]
    regs = summary["regressions"]
    if regs:
        out += [
            f"- {c['device']}/{c['dtype']} {c['d_model']}×{c['d_hidden']} {c['mode']} "
            f"**{c['candidate']}** at {c['rows']} rows: {c['speedup_geomean']:.2f}× "
            f"[{c['ci_low']:.2f}, {c['ci_high']:.2f}]"
            for c in regs
        ]
    else:
        out.append("- none")
    out += [
        "",
        "## Bandwidth roofline (pipelined mode)",
        "",
        "Achieved GB/s is **derived** (weight bytes ÷ measured p50). The nominal bandwidth and floor are",
        "**theoretical** (vendor-nominal), not observed.",
        "",
        "| device | dtype | model | impl | rows | p50 µs | achieved GB/s | % of nominal | floor µs |",
        "|---|---|---|---|---|---|---|---|---|",
    ]
    for b in summary["benchmarks"]:
        rf = b.get("roofline")
        if not rf or rf.get("achieved_gbps") is None:
            continue
        frac = rf.get("fraction_of_nominal")
        out.append(
            f"| {b['device']} | {b['dtype']} | {b['d_model']}×{b['d_hidden']} | {b['impl']} "
            f"| {b['rows']} | {_f(b['host_us']['p50'])} | {_f(rf['achieved_gbps'], 1)} "
            f"| {_f(None if frac is None else 100 * frac)}% | {_f(rf.get('floor_us'))} |"
        )
    out += [
        "",
        "## Serving (measured, open-loop replay)",
        "",
        "| impl | policy | arrival | rate rps | p50 µs | p99 µs | miss rate | goodput rows/s | batch | util |",
        "|---|---|---|---|---|---|---|---|---|---|",
    ]
    for s in sorted(
        summary["serving"], key=lambda s: (s["impl"], s["policy"], s["arrival"], s["rate_rps"])
    ):
        lat = s["latency_us"]
        out.append(
            f"| {s['impl']} | {s['policy']} | {s['arrival']} | {_f(s['rate_rps'])} "
            f"| {_f(lat.get('p50'))} | {_f(lat.get('p99'))} | {s['deadline_miss_rate']:.3f} "
            f"| {_f(s['goodput_rows_per_s'])} | {_f(s['mean_batch_rows'], 1)} "
            f"| {s['utilization']:.2f} |"
        )
    env_s = summary.get("envelope") or {}
    if env_s:
        out += [
            "",
            f"Operating envelope (≤{100 * env_s['miss_budget']:.0f}% misses, "
            f"{env_s['deadline_us'] / 1000:.0f} ms deadline): "
            + ", ".join(
                f"{k}: {v if v is not None else 'none'}"
                for k, v in sorted(env_s["max_sustainable_rps"].items())
            ),
        ]
    ig = summary.get("idle_gap")
    if ig:
        out += ["", "## Idle-gap sensitivity (derived, paired)", ""]
        for g, v in ig["slowdown_vs_no_gap"].items():
            out.append(
                f"- {float(g) / 1000:g} ms gap: {v['geomean']:.2f}× "
                f"[{v['ci_low']:.2f}, {v['ci_high']:.2f}], {v['verdict']}"
            )
    out += ["", "## Kernel launch counts per forward (measured)", ""]
    for k, v in sorted(summary["kernels"]["launches_per_forward"].items()):
        note = "" if v["complete"] else " (Inductor kernels not counted)"
        out.append(f"- {k}: {v['total']:g} (ATen {v['aten']:g}, custom {v['custom'] or 0:g}){note}")
    out += ["", "## Correctness (measured)", ""]
    corr = summary["correctness"]
    out.append(
        f"- Phase 1 baseline records: {sum(bool(c['passed']) for c in corr)}/{len(corr)} pass"
    )
    bad = [b for b in summary["benchmarks"] if b.get("correct") is False]
    out.append(f"- Every benchmarked configuration was checked first: {len(bad)} failures")
    return "\n".join(out) + "\n"
